// matrix-green-fill-interactive — interactive background, generated by themeanizor.
// Dependency-free ES module. Usage:
//   import { mountBackground } from "./background.js";
//   const dispose = mountBackground(document.body);        // uses DEFAULT_CONFIG
//   mountBackground(document.body, { radius: 500 });       // or override fields
// The canvas is fixed, full-viewport, pointer-transparent, z-index 0; put your
// UI above it (position relative/absolute with z-index >= 1).

export const DEFAULT_CONFIG = {
  "pattern": "cells",
  "cell": 28,
  "inset": 1,
  "corner": 7,
  "lineWidth": 2.5,
  "fillCells": true,
  "radius": 260,
  "shape": "custom:elmrs685ucb",
  "trail": "comet",
  "attack": 0.08,
  "release": 0.015,
  "follow": 0.22,
  "jitter": 0.85,
  "strokeAlpha": 0.7,
  "washAlpha": 0.055,
  "glowWidth": 1,
  "customPatterns": [],
  "customShapes": [
    {
      "id": "elmrs685ucb",
      "name": "Hexagon",
      "sides": 6,
      "star": 1,
      "rotation": 0
    }
  ],
  "image": {
    "src": "",
    "fit": "cover",
    "opacity": 0.5,
    "blur": 0,
    "brightness": 1,
    "hue": 0
  }
};

const FALLBACK_ACCENT = [126, 226, 98];

function accentRgb() {
  const raw = getComputedStyle(document.documentElement).getPropertyValue("--accent").trim();
  const hex = raw.startsWith("#") ? raw.slice(1) : "";
  if (hex.length === 3) return [0, 1, 2].map((i) => parseInt(hex[i] + hex[i], 16));
  if (hex.length >= 6)
    return [parseInt(hex.slice(0, 2), 16), parseInt(hex.slice(2, 4), 16), parseInt(hex.slice(4, 6), 16)];
  const m = raw.match(/rgba?\(\s*(\d+)[,\s]+(\d+)[,\s]+(\d+)/);
  if (m) return [Number(m[1]), Number(m[2]), Number(m[3])];
  return FALLBACK_ACCENT;
}

function hash2(a, b) {
  let h = (a * 374761393 + b * 668265263) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967295;
}

function polyDist(dx, dy, s) {
  const step = Math.PI / Math.max(3, s.sides);
  let ang = Math.atan2(dy, dx) - (s.rotation * Math.PI) / 180;
  ang = ((ang % (2 * step)) + 2 * step) % (2 * step) - step;
  let b = Math.cos(step) / Math.cos(ang);
  if (s.star < 1) {
    const t = Math.abs(ang) / step;
    b *= s.star + (1 - s.star) * t;
  }
  return Math.hypot(dx, dy) / Math.max(0.2, b);
}

function shapedDist(dx, dy, cfg) {
  const shape = cfg.shape;
  if (shape.startsWith("custom:")) {
    const cs = (cfg.customShapes || []).find((c) => "custom:" + c.id === shape);
    if (cs) return polyDist(dx, dy, cs);
  }
  switch (shape) {
    case "square": return Math.max(Math.abs(dx), Math.abs(dy));
    case "diamond": return (Math.abs(dx) + Math.abs(dy)) * 0.72;
    case "ellipse-h": return Math.hypot(dx * 0.62, dy * 1.45);
    case "ellipse-v": return Math.hypot(dx * 1.45, dy * 0.62);
    default: return Math.hypot(dx, dy);
  }
}

export function mountBackground(host, config) {
  const cfg = Object.assign({}, DEFAULT_CONFIG, config || {});
  const layer = document.createElement("div");
  layer.style.cssText = "position:fixed;inset:0;z-index:0;pointer-events:none;";
  const im = cfg.image || {};
  if (im.src) {
    const img = document.createElement("div");
    const size = im.fit === "tile" ? "auto" : im.fit;
    const repeat = im.fit === "tile" ? "repeat" : "no-repeat";
    img.style.cssText =
      "position:absolute;inset:0;background-image:url('" + im.src + "');" +
      "background-size:" + size + ";background-repeat:" + repeat + ";background-position:center;" +
      "opacity:" + im.opacity + ";filter:blur(" + im.blur + "px) brightness(" + im.brightness + ") hue-rotate(" + im.hue + "deg);";
    layer.appendChild(img);
  }
  const canvas = document.createElement("canvas");
  layer.style.background = "transparent";
  canvas.style.background = "transparent";
  layer.appendChild(canvas);
  host.prepend(layer);
  const ctx = canvas.getContext("2d", { alpha: true });
  const pathCache = new Map();

  let [ar, ag, ab] = accentRgb();
  const HEX = cfg.pattern === "hexes";
  const stepY = HEX ? cfg.cell * 0.8660254 : cfg.cell;
  function centerX(i, j) { return (i + 0.5 + (HEX && (j & 1) ? 0.5 : 0)) * cfg.cell; }
  function centerY(j) { return (j + 0.5) * stepY; }
  let w = 0, h = 0, dpr = 1;
  const cells = new Map();
  const key = (i, j) => i * 8192 + j;
  const pointer = { x: -9999, y: -9999, tx: -9999, ty: -9999, active: false };
  const trail = [];

  function resize() {
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    w = window.innerWidth;
    h = window.innerHeight;
    canvas.width = Math.floor(w * dpr);
    canvas.height = Math.floor(h * dpr);
    canvas.style.width = w + "px";
    canvas.style.height = h + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    [ar, ag, ab] = accentRgb();
  }

  function onMove(e) { pointer.tx = e.clientX; pointer.ty = e.clientY; pointer.active = true; }
  function onLeave() { pointer.active = false; }

  function stamp(px, py, scale) {
    const R = cfg.radius * (scale < 1 ? 0.55 + 0.45 * scale : 1);
    const i0 = Math.floor((px - R) / cfg.cell);
    const i1 = Math.floor((px + R) / cfg.cell);
    const j0 = Math.floor((py - R) / stepY);
    const j1 = Math.floor((py + R) / stepY);
    for (let i = i0; i <= i1; i++) {
      for (let j = j0; j <= j1; j++) {
        const cx = centerX(i, j);
        const cy = centerY(j);
        const d = shapedDist(cx - px, cy - py, cfg);
        if (d >= R) continue;
        let t = 1 - d / R;
        t = t * t * (3 - 2 * t);
        const jit = 1 - cfg.jitter + cfg.jitter * hash2(i, j);
        const target = t * t * jit * scale;
        const k = key(i, j);
        const cur = cells.get(k) || 0;
        if (cfg.trail === "pulse") {
          if (cur < 0.02 && target > 0.05) cells.set(k, target);
        } else if (target > cur) {
          cells.set(k, cur + (target - cur) * cfg.attack);
        }
      }
    }
  }

  function drawCell(x, y, size) {
    if (cfg.pattern.startsWith("custom:")) {
      const cp = (cfg.customPatterns || []).find((c) => "custom:" + c.id === cfg.pattern);
      if (cp) {
        let p = pathCache.get(cp.id);
        if (!p) { p = new Path2D(cp.path); pathCache.set(cp.id, p); }
        const s = size / 24;
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(s, s);
        ctx.lineWidth = cfg.lineWidth / s;
        if (cfg.fillCells) ctx.fill(p); else ctx.stroke(p);
        ctx.restore();
        return;
      }
    }
    const half = size / 2;
    const cx = x + half;
    const cy = y + half;
    let strokeOnly = false;
    ctx.beginPath();
    switch (cfg.pattern) {
      case "dots":
        ctx.arc(cx, cy, Math.max(1.2, size * 0.14), 0, Math.PI * 2);
        break;
      case "crosses": {
        const a = size * 0.22;
        ctx.moveTo(cx - a, cy); ctx.lineTo(cx + a, cy);
        ctx.moveTo(cx, cy - a); ctx.lineTo(cx, cy + a);
        strokeOnly = true;
        break;
      }
      case "lines":
        ctx.moveTo(x, y + size); ctx.lineTo(x + size, y + size);
        ctx.moveTo(x + size, y); ctx.lineTo(x + size, y + size);
        strokeOnly = true;
        break;
      case "hexes": {
        const R = half * 0.96;
        const r = Math.min(cfg.corner, R * 0.42);
        const pts = [];
        for (let k = 0; k < 6; k++) {
          const a = -Math.PI / 2 + (k * Math.PI) / 3;
          pts.push([cx + R * Math.cos(a), cy + R * Math.sin(a)]);
        }
        const m0 = [(pts[0][0] + pts[1][0]) / 2, (pts[0][1] + pts[1][1]) / 2];
        ctx.moveTo(m0[0], m0[1]);
        for (let k = 1; k <= 6; k++) {
          const v = pts[k % 6];
          const n = pts[(k + 1) % 6];
          ctx.arcTo(v[0], v[1], (v[0] + n[0]) / 2, (v[1] + n[1]) / 2, r);
        }
        ctx.closePath();
        break;
      }
      case "diamonds":
        ctx.moveTo(cx, y); ctx.lineTo(x + size, cy);
        ctx.lineTo(cx, y + size); ctx.lineTo(x, cy);
        ctx.closePath();
        break;
      default: {
        const r = Math.min(cfg.corner, half);
        ctx.moveTo(x + r, y);
        ctx.lineTo(x + size - r, y);
        ctx.arcTo(x + size, y, x + size, y + r, r);
        ctx.lineTo(x + size, y + size - r);
        ctx.arcTo(x + size, y + size, x + size - r, y + size, r);
        ctx.lineTo(x + r, y + size);
        ctx.arcTo(x, y + size, x, y + size - r, r);
        ctx.lineTo(x, y + r);
        ctx.arcTo(x, y, x + r, y, r);
        ctx.closePath();
      }
    }
    if (cfg.fillCells && !strokeOnly) ctx.fill(); else ctx.stroke();
  }

  function draw() {
    pointer.x += (pointer.tx - pointer.x) * cfg.follow;
    pointer.y += (pointer.ty - pointer.y) * cfg.follow;
    ctx.clearRect(0, 0, w, h);
    const now = performance.now();
    const px = pointer.x, py = pointer.y;

    if (pointer.active) {
      stamp(px, py, 1);
      if (cfg.trail === "comet") {
        const last = trail[trail.length - 1];
        if (!last || Math.hypot(px - last.x, py - last.y) > 14) trail.push({ x: px, y: py, t: now });
        const life = 260 + 5200 * Math.max(0.004, 0.12 - cfg.release);
        for (let i = trail.length - 1; i >= 0; i--) {
          const age = (now - trail[i].t) / life;
          if (age >= 1) { trail.splice(i, 1); continue; }
          stamp(trail[i].x, trail[i].y, (1 - age) * 0.85);
        }
      }
      if (cfg.washAlpha > 0.001) {
        const wash = ctx.createRadialGradient(px, py, 0, px, py, cfg.radius);
        wash.addColorStop(0, "rgba(" + ar + "," + ag + "," + ab + "," + cfg.washAlpha + ")");
        wash.addColorStop(1, "rgba(" + ar + "," + ag + "," + ab + ",0)");
        ctx.fillStyle = wash;
        ctx.fillRect(px - cfg.radius, py - cfg.radius, cfg.radius * 2, cfg.radius * 2);
      }
    } else {
      trail.length = 0;
    }

    const rel = cfg.trail === "pulse" ? Math.max(cfg.release, 0.02) * 1.6 : cfg.release;
    ctx.lineWidth = cfg.lineWidth * (cfg.glowWidth || 1);
    const col = "rgba(" + ar + "," + ag + "," + ab + "," + cfg.strokeAlpha + ")";
    ctx.strokeStyle = col;
    ctx.fillStyle = col;
    const size = cfg.cell - cfg.inset * 2;

    for (const [k, v] of cells) {
      const nv = v * (1 - rel);
      if (nv < 0.015) { cells.delete(k); continue; }
      cells.set(k, nv);
      const i = Math.floor(k / 8192);
      const j = k - i * 8192;
      ctx.globalAlpha = nv;
      if (HEX) drawCell(centerX(i, j) - size / 2, centerY(j) - size / 2, size);
      else drawCell(i * cfg.cell + cfg.inset + 0.5, j * cfg.cell + cfg.inset + 0.5, size);
    }
    ctx.globalAlpha = 1;
    raf = requestAnimationFrame(draw);
  }

  let raf = 0;
  resize();
  draw();
  window.addEventListener("resize", resize);
  window.addEventListener("pointermove", onMove);
  document.documentElement.addEventListener("pointerleave", onLeave);

  return function dispose() {
    cancelAnimationFrame(raf);
    window.removeEventListener("resize", resize);
    window.removeEventListener("pointermove", onMove);
    document.documentElement.removeEventListener("pointerleave", onLeave);
    layer.remove();
  };
}
